args.command:
python3 -c 'import os; files=[]; terms=("driver","Driver","factory","Factory");
for root,dirs,fs in os.walk("."):
 dirs[:]=[d for d in dirs if d not in (".git","node_modules")]
 for f in fs:
  p=os.path.join(root,f)
  if f.endswith(".go"):
   try:
    s=open(p).read()
   except: continue
   if any(t in s for t in terms): print(p)
'

